"""Exercise the real CycloneDX POM preflight with a local parent-POM fixture.

This is intentionally an opt-in integration check: it invokes the repository's
Gradle wrapper and includes the real build-logic composite build.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import tempfile
import zipfile
import xml.etree.ElementTree as ET


GROUP = "org.example.fixture"
CHILD = "licensed-child"
PARENT = "license-parent"
VERSION = "1.0"
LICENSE_NAME = "Apache License, Version 2.0"
LICENSE_URL = "https://www.apache.org/licenses/LICENSE-2.0"
MAVEN_NS = "http://maven.apache.org/POM/4.0.0"
VERIFY_NS = "https://schema.gradle.org/dependency-verification"


def digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def artifact_dir(repo: Path, group: str, name: str) -> Path:
    return repo / group.replace(".", "/") / name / VERSION


def write_artifact(repo: Path, group: str, name: str, suffix: str, content: bytes) -> Path:
    path = artifact_dir(repo, group, name) / f"{name}-{VERSION}.{suffix}"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(content)
    return path


def make_fixture(repo: Path, fixture: Path) -> tuple[Path, Path]:
    fake_repo = fixture / "fake-repo"
    ET.register_namespace("", VERIFY_NS)
    root = ET.parse(repo / "gradle/verification-metadata.xml")
    root_el = root.getroot()
    components = root_el.find(f"{{{VERIFY_NS}}}components")
    if components is None:
        raise RuntimeError("repository verification metadata has no components element")

    def register(group: str, name: str, files: list[Path]) -> None:
        component = ET.SubElement(components, f"{{{VERIFY_NS}}}component", {
            "group": group, "name": name, "version": VERSION,
        })
        for file in files:
            artifact = ET.SubElement(component, f"{{{VERIFY_NS}}}artifact", {"name": file.name})
            ET.SubElement(artifact, f"{{{VERIFY_NS}}}sha256", {
                "value": digest(file), "origin": "Generated by isolated SBOM fixture",
            })

    jar = artifact_dir(fake_repo, GROUP, CHILD) / f"{CHILD}-{VERSION}.jar"
    jar.parent.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(jar, "w") as archive:
        archive.writestr("META-INF/MANIFEST.MF", "Manifest-Version: 1.0\n")
    module = {
        "formatVersion": "1.1",
        "component": {"group": GROUP, "module": CHILD, "version": VERSION},
        "createdBy": {"gradle": {"version": "9.0"}},
        "variants": [{
            "name": "runtimeElements",
            "attributes": {"org.gradle.category": "library", "org.gradle.usage": "java-runtime"},
            "files": [{"name": jar.name, "url": jar.name, "size": len(jar.read_bytes()),
                       "sha256": digest(jar)}],
        }],
    }
    module_file = write_artifact(fake_repo, GROUP, CHILD, "module",
                                 (json.dumps(module, indent=2) + "\n").encode())

    child_pom = f'''<project xmlns="{MAVEN_NS}">
  <modelVersion>4.0.0</modelVersion>
  <!-- do_not_remove: published-with-gradle-metadata -->
  <parent><groupId>{GROUP}</groupId><artifactId>{PARENT}</artifactId><version>{VERSION}</version><relativePath/></parent>
  <groupId>{GROUP}</groupId><artifactId>{CHILD}</artifactId><version>{VERSION}</version>
</project>
'''.encode()
    child_pom_file = write_artifact(fake_repo, GROUP, CHILD, "pom", child_pom)
    parent_pom = f'''<project xmlns="{MAVEN_NS}">
  <modelVersion>4.0.0</modelVersion>
  <groupId>{GROUP}</groupId><artifactId>{PARENT}</artifactId><version>{VERSION}</version><packaging>pom</packaging>
  <licenses><license><name>{LICENSE_NAME}</name><url>{LICENSE_URL}</url></license></licenses>
</project>
'''.encode()
    parent_pom_file = write_artifact(fake_repo, GROUP, PARENT, "pom", parent_pom)

    register(GROUP, CHILD, [jar, module_file, child_pom_file])
    register(GROUP, PARENT, [parent_pom_file])
    verification = fixture / "gradle/verification-metadata.xml"
    verification.parent.mkdir(parents=True)
    root.write(verification, encoding="utf-8", xml_declaration=True)
    heap_setting = next(
        (line for line in (repo / "gradle.properties").read_text().splitlines()
         if line.startswith("org.gradle.jvmargs=")),
        None,
    )
    if heap_setting is None:
        raise RuntimeError("repository gradle.properties has no org.gradle.jvmargs setting")
    (fixture / "gradle.properties").write_text(
        heap_setting + "\nkotlin.stdlib.default.dependency=false\n",
    )

    (fixture / "gradle/libs.versions.toml").parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(repo / "openbank-libs/gradle/libs.versions.toml",
                    fixture / "gradle/libs.versions.toml")
    (fixture / "settings.gradle.kts").write_text(f'''pluginManagement {{
    includeBuild("{(repo / "build-logic").as_posix()}")
    repositories {{
        maven("https://maven-central.storage-download.googleapis.com/maven2/")
        gradlePluginPortal()
        mavenCentral()
    }}
}}
gradle.beforeProject {{
    buildscript.configurations.configureEach {{
        resolutionStrategy.force("org.freemarker:freemarker:2.3.35")
    }}
}}
rootProject.name = "sbom-effective-model-fixture"
include(":probe")
''')
    (fixture / "build.gradle.kts").write_text("// Isolated integration fixture root.\n")
    probe = fixture / "probe"
    probe.mkdir()
    (probe / "build.gradle.kts").write_text(f'''plugins {{
    alias(libs.plugins.kotlin.jvm)
    alias(libs.plugins.kotlin.allopen)
    alias(libs.plugins.quarkus)
    alias(libs.plugins.cyclonedx)
    alias(libs.plugins.kover)
    id("openbank.dependency-vulnerability-pins")
    id("openbank.cyclonedx-verification")
}}

group = "com.openbank"
version = "0.1.0-SNAPSHOT"
repositories {{ maven {{ url = uri(rootProject.file("fake-repo")) }} }}
dependencies {{ runtimeOnly("{GROUP}:{CHILD}:{VERSION}") }}
tasks.named<org.cyclonedx.gradle.CycloneDxTask>("cyclonedxBom") {{
    setIncludeConfigs(listOf("runtimeClasspath"))
    setOutputFormat("all")
}}
''')
    return verification, parent_pom_file


def run_gradle(repo: Path, fixture: Path, offline: bool, timeout: int) -> subprocess.CompletedProcess[str]:
    command = [str(repo / "gradlew"), "-p", str(fixture), "--no-daemon", "--console=plain",
               "--dependency-verification=strict", "--no-build-cache", "--no-parallel",
               "--max-workers=1"]
    if offline:
        command.append("--offline")
    command.extend(["--rerun-tasks", ":probe:cyclonedxBom"])
    env = os.environ.copy()
    env.pop("REPOSILITE_MIRROR_URL", None)
    return subprocess.run(command, cwd=repo, env=env, text=True, stdout=subprocess.PIPE,
                          stderr=subprocess.STDOUT, timeout=timeout, check=False)


def bom_contains_license(path: Path) -> bool:
    data = json.loads(path.read_text())
    components = data.get("components", [])
    return any(
        component.get("name") == CHILD
        and any(
            license_obj.get("license", {}).get("name") == LICENSE_NAME
            or license_obj.get("license", {}).get("url") == LICENSE_URL
            or license_obj.get("license", {}).get("id") == "Apache-2.0"
            for license_obj in component.get("licenses", [])
        )
        for component in components
    )


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--offline", action="store_true", help="forbid Gradle network access")
    parser.add_argument("--timeout", type=int, default=240, help="timeout per fixture build, seconds")
    args = parser.parse_args()
    repo = Path(__file__).resolve().parents[2]
    source_verification = repo / "gradle/verification-metadata.xml"
    source_digest = digest(source_verification)

    with tempfile.TemporaryDirectory(prefix="sbom-effective-model-") as temp:
        fixture = Path(temp)
        verification, parent_pom = make_fixture(repo, fixture)
        first = run_gradle(repo, fixture, args.offline, args.timeout)
        bom = fixture / "probe/build/reports/bom.json"
        if first.returncode != 0:
            print("positive fixture failed; Gradle output:")
            print(first.stdout)
            return 1
        xml_bom = bom.with_suffix(".xml")
        if not bom.is_file() or not xml_bom.is_file():
            print("positive fixture did not emit both expected CycloneDX reports")
            return 1
        if not bom_contains_license(bom):
            print("positive fixture did not emit the inherited Apache license in the child JSON BOM")
            return 1
        report_files = [bom, xml_bom]
        report_snapshots = {path: path.read_bytes() for path in report_files}
        verification_before = verification.read_bytes()

        tree = ET.parse(verification)
        comp = tree.getroot().find(f"{{{VERIFY_NS}}}components/{{{VERIFY_NS}}}component[@group='{GROUP}'][@name='{PARENT}']")
        if comp is None:
            print("fixture parent component missing from verification metadata")
            return 1
        for artifact in list(comp.findall(f"{{{VERIFY_NS}}}artifact")):
            if artifact.get("name") == parent_pom.name:
                comp.remove(artifact)
        if not list(comp):
            tree.getroot().find(f"{{{VERIFY_NS}}}components").remove(comp)
        tree.write(verification, encoding="utf-8", xml_declaration=True)
        verification_after_edit = verification.read_bytes()
        if verification_after_edit == verification_before:
            print("test setup error: removing the parent-POM checksum changed no fixture bytes")
            return 1

        second = run_gradle(repo, fixture, args.offline, args.timeout)
        if second.returncode == 0:
            print("negative fixture unexpectedly succeeded after parent-POM checksum removal")
            return 1
        for path, previous_bytes in report_snapshots.items():
            if path.read_bytes() != previous_bytes:
                print(f"negative fixture changed the previous report: {path.name}")
                return 1
        if verification.read_bytes() != verification_after_edit:
            print("Gradle modified the fixture verification metadata during the negative check")
            return 1
        if digest(source_verification) != source_digest:
            print("repository verification metadata changed during the isolated fixture")
            return 1
        output = second.stdout.lower()
        if (
            "> task :probe:cyclonedxbom failed" not in output
            or "pom_preflight external_components=" not in output
            or "pom_preflight external_components=1" not in output
            or "pom_preflight resolved_models=" in output
            or "dependency verification failed for org.example.fixture:licensed-child:1.0" not in output
            or "license-parent-1.0.pom" not in output
            or PARENT.lower() not in output
        ):
            print("negative fixture failed, but output did not prove task-boundary parent-POM verification failure")
            print("\n".join(second.stdout.splitlines()[-60:]))
            return 1

        print("PASS: real CycloneDX task includes inherited Apache license")
        print("PASS: unpinned parent POM fails closed before changing BOM or verification metadata")
        print(f"fixture builds: positive={first.returncode}, negative={second.returncode}; "
              f"source verification metadata unchanged={digest(source_verification) == source_digest}")
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except subprocess.TimeoutExpired as error:
        print(f"fixture Gradle build exceeded timeout ({error.timeout}s)", file=sys.stderr)
        raise SystemExit(2) from error
